using System.Buffers.Binary;
using System.Security.Cryptography;
using Spyro.Editor.Core.Scene;

namespace Spyro.Editor.Core.Exporting;

/// <summary>
/// Recaptures private schemas against one actual retained resource Body or the
/// closed terrain revision of its placed child. Its
/// graph describes installed immutable storage, not another resource import or
/// complete native behavior closure. The replacement Scene and any later Body
/// remain separate owners; generated bytes never become Original source reads.
/// </summary>
internal sealed class NativeFreshLockedChestSceneStorageSource
{
    private const string Policy="source-owned-mixed-family-chest-scene-storage-v1";
    private readonly NativeFreshMobyFamilyCompositionPlan _resources;
    private readonly NativeFreshLockedChestResearchHostExtension _host;
    private readonly NativeFreshTiledFamilyTerrainRevision? _terrain;
    private readonly byte[] _bodySnapshot;
    private readonly Dictionary<NativeByteExtent,(NativeMobyDependencyRead Read,Func<NativeByteExtent,byte[]> Reader)> _reads=[];

    private NativeFreshLockedChestSceneStorageSource(NativeFreshMobyFamilyCompositionPlan resources,
        NativeFreshLockedChestResearchHostExtension host,NativeFreshTiledFamilyTerrainRevision? terrain=null)
    {
        _resources=resources;_host=host;_terrain=terrain;Source=host.FamilySourceAncestor;RequireOwners();
        var parent=host.CurrentExecutableAncestor.FamilyCompositionAncestor!;
        var wizard=parent.Placements[0].WizardAsset??throw new InvalidDataException("Chest storage lost its actual Wizard source.");
        var passive=parent.Placements[1].PassiveAsset??throw new InvalidDataException("Chest storage lost its actual passive source.");
        var wizardRows=wizard.CapturePrivateStorageRows();var passiveRows=passive.InstanceTemplate.Rows;
        passive.RequireRetainedOwners();
        if(passive.InstanceTemplate.Globals.Count!=0)
            throw new InvalidDataException("The retained passive source must not silently lose mutable global reservations.");
        foreach(var row in wizardRows)RegisterRow(row,wizard.ReadPrivateSource);
        foreach(var row in passiveRows)RegisterRow(row,passive.ReadSource);
        foreach(var row in Source.PrivateRows)RegisterRow(row,Source.ReadSource);
        var executable=Source.ResourceInputs["key.special-renderer-and-global-routines"].Single().Extent.Space;
        if(Source.MutableGlobals.Count!=2||Source.MutableGlobals.Any(g=>!ReferenceEquals(g.ExecutableDomain,executable)))
            throw new InvalidDataException("Chest storage requires both mutable globals in the actual retained chest executable domain.");
        foreach(var global in Source.MutableGlobals)
        foreach(var read in global.Consumers)Register(read,Source.ReadSource);

        byte[] body=terrain is null?resources.CopyLevelData():
            NativeFreshTiledFamilyBodyPlan.CreateTerrainLayout(terrain).Expand(terrain.PlacementAncestor.CopyLevelData());
        if(terrain is null)resources.RequireExactLevelData(body);
        _bodySnapshot=terrain is null?[]:body.ToArray();
        FinalBodyDomain=terrain is null?resources.FinalBodyDomain:new(NativeAddressKind.LevelData,
            "fresh-tiled-family-body:"+terrain.PlanSha256,NativeAddressRevision.Final,body.Length);
        if(FinalBodyDomain.Kind!=NativeAddressKind.LevelData||FinalBodyDomain.Revision!=NativeAddressRevision.Final||
            FinalBodyDomain.ByteLength!=body.Length||body.Length<0x800)
            throw new InvalidDataException("Chest storage requires its complete actual Final resource Body.");
        var town=Source.ResourceInputs["effects.native-registration"].Single().Extent.Space;
        byte[] originalHeader=Source.ReadSource(new(town,0,0x800));
        var headerRead=new NativeMobyDependencyRead("original-town-header",new(town,0,0x800),Hash(originalHeader));
        Register(headerRead,Source.ReadSource);
        List<NativeMobyDependencyNode> nodes=[];
        AddOwner("retained-body.header",NativeMobyDependencyKind.ActorRegistration,0,0x800,[headerRead]);
        int cursor=0x800,sceneOffset=0,sceneLength=0;
        for(int index=0;index<8;index++)
        {
            int at=Word(body,index*8),length=Word(body,index*8+4);
            if(at!=cursor||length<=0||at>body.Length-length)
                throw new InvalidDataException("Retained Body subfiles must partition its complete immutable storage and existing Scene.");
            cursor=checked(at+length);
            if(index==3){sceneOffset=at;sceneLength=length;continue;}
            int sourceAt=Word(originalHeader,index*8),sourceLength=Word(originalHeader,index*8+4);
            var extent=new NativeByteExtent(town,sourceAt,sourceLength);
            var read=new NativeMobyDependencyRead("original-town-subfile-"+index,extent,Hash(Source.ReadSource(extent)));
            Register(read,Source.ReadSource);
            List<NativeMobyDependencyRead> evidence=[read];
            if(index==2)
            {
                var spans=wizard.SourceSpans.Where(s=>s.OwnerId is "wizard.model" or "bolt.model" or "player.animation8").ToArray();
                if(spans.Length!=3||spans.Select(s=>s.OwnerId).Distinct().Count()!=3)
                    throw new InvalidDataException("Retained models lost the three complete actual Wizard model/animation source owners.");
                foreach(var span in spans)
                {
                    var modelRead=new NativeMobyDependencyRead(span.OwnerId,new(wizard.OriginalDataDomain,
                        span.SourceWadOffset-NativeWizardFamilyAssetSource.DonorWadOffset,span.ByteLength),span.Sha256);
                    Register(modelRead,wizard.ReadPrivateSource);evidence.Add(modelRead);
                }
                foreach(var sourceRead in passive.AssetGraph.Nodes.SelectMany(n=>n.Reads))
                {
                    var passiveRead=sourceRead with{Id="passive."+sourceRead.Id};
                    Register(passiveRead,passive.ReadSource);evidence.Add(passiveRead);
                }
                var chestReads=new[]{Source.PackageRead}.Concat(new[]{0x135,0x136,0x137}
                    .Select(id=>Source.ResourceInputs["effects.native-debris."+id].Single())).ToArray();
                for(int i=0;i<chestReads.Length;i++)
                {
                    var chestRead=chestReads[i] with{Id="chest.model."+i};
                    Register(chestRead,Source.ReadSource);evidence.Add(chestRead);
                }
            }
            AddOwner("retained-body.subfile-"+index,index==2?NativeMobyDependencyKind.ActorPackage:NativeMobyDependencyKind.Bundle,
                at,length,evidence.ToArray());
        }
        byte[] retainedScene=terrain is null?resources.CopyScene():terrain.PlacementAncestor.CopyScene();
        if(cursor!=body.Length||sceneLength!=retainedScene.Length||
            !body.AsSpan(sceneOffset,sceneLength).SequenceEqual(retainedScene))
            throw new InvalidDataException("Retained storage partition must exclude exactly the complete existing Scene and no other bytes.");
        Graph=NativeMobyDependencyClosureCompiler.Compile(nodes,nodes.Select(n=>n.Id),ReadSource);
        if(Graph.Nodes.Count!=8||Graph.Installs.Count!=8||Graph.References.Count!=0||Graph.Nodes.Any(n=>n.Preserved.Count!=0)||
            Graph.Installs.Sum(i=>i.Destination.ByteLength)!=body.Length-sceneLength)
            throw new InvalidDataException("Chest storage must own exactly the header and seven disjoint non-Scene subfiles.");
        foreach(var install in Graph.Installs)
            if(!ReferenceEquals(install.Destination.Space,FinalBodyDomain)||
                install.Destination.Offset<sceneOffset+sceneLength&&sceneOffset<install.Destination.EndExclusive||
                !Graph.CopyPayload(install.NodeId).AsSpan().SequenceEqual(body.AsSpan((int)install.Destination.Offset,(int)install.Destination.ByteLength)))
                throw new InvalidDataException("Storage graph escaped its actual installed Final Body or claimed the excluded Scene.");
        string policy=terrain is null?Policy:"source-owned-tiled-family-chest-scene-storage-v1";
        WizardTemplate=NativeMobyDependencyInstanceTemplate.Capture(policy,wizardRows,[],Graph,ReadSource);
        PassiveTemplate=NativeMobyDependencyInstanceTemplate.Capture(policy,passiveRows,[],Graph,ReadSource);
        ChestTemplate=NativeMobyDependencyInstanceTemplate.Capture(policy,Source.PrivateRows,Source.MutableGlobals,Graph,ReadSource);
        RequireOwners();RequireRetainedBody(body);

        void AddOwner(string id,NativeMobyDependencyKind kind,int at,int length,NativeMobyDependencyRead[] evidence)
        {
            // Original reads establish provenance; these derived payloads come
            // from the actual resource child or the closed terrain composer,
            // not a replay or equality claim about the retail subfile.
            byte[] installed=body.AsSpan(at,length).ToArray();
            nodes.Add(new(id,kind,NativeMobyDependencyResolution.ImportFromSource,NativeMobyDependencySharing.Immutable,
                terrain?.PlanSha256??resources.PlanSha256,[],evidence,context=>
                {
                    RequireOwners();RequireRetainedBody(body);
                    foreach(var sourceRead in evidence)
                        if(!context.Read(sourceRead.Id).AsSpan().SequenceEqual(ReadSource(sourceRead.Extent)))
                            throw new InvalidDataException("Installed storage lost its actual declared Original provenance.");
                    return new(installed,[new("installed-storage",new(FinalBodyDomain,at,length))],[]);
                }));
        }
    }

    internal NativeLockedChestFamilySource Source{get;}
    internal NativeAddressSpace FinalBodyDomain{get;}
    internal NativeMobyDependencyClosurePlan Graph{get;}
    internal NativeMobyDependencyInstanceTemplate WizardTemplate{get;}
    internal NativeMobyDependencyInstanceTemplate PassiveTemplate{get;}
    internal NativeMobyDependencyInstanceTemplate ChestTemplate{get;}
    internal static NativeFreshLockedChestSceneStorageSource Capture(NativeFreshMobyFamilyCompositionPlan resources,
        NativeFreshLockedChestResearchHostExtension host)
    {ArgumentNullException.ThrowIfNull(resources);ArgumentNullException.ThrowIfNull(host);return new(resources,host);}
    // Closed producer arm: callers cannot supply generated bytes, address
    // domains, policy names or callbacks as source authority.
    internal static NativeFreshLockedChestSceneStorageSource CaptureForTerrainRevision(NativeFreshTiledFamilyTerrainRevision terrain)
    {ArgumentNullException.ThrowIfNull(terrain);return new(terrain.ResourceAncestor,terrain.HostAncestor,terrain);}
    internal void RequireTerrainAncestry(NativeFreshTiledFamilyTerrainRevision terrain)
    {
        ArgumentNullException.ThrowIfNull(terrain);
        if(!ReferenceEquals(terrain,_terrain))throw new InvalidDataException("Scene storage retains its actual terrain revision, not an equal owner or the legacy resource arm.");
        RequireOwners();
    }
    internal byte[] ReadSource(NativeByteExtent extent)
    {
        ArgumentNullException.ThrowIfNull(extent);
        if(extent.Space.Revision!=NativeAddressRevision.Original||!_reads.TryGetValue(extent,out var source))
            throw new InvalidDataException("Chest scene storage may read only its exact declared retained Original extents.");
        byte[] bytes=source.Reader(extent)?.ToArray()??throw new InvalidDataException("Retained scene storage source returned no bytes.");
        if(bytes.LongLength!=extent.ByteLength||Hash(bytes)!=source.Read.ExpectedSha256)
            throw new InvalidDataException("Retained scene storage source changed its complete Original preimage.");
        return bytes;
    }
    private void RegisterRow(NativeMobyDependencyPrivateSchema row,Func<NativeByteExtent,byte[]> reader)
    {Register(row.Row,reader);Register(row.Properties,reader);}
    private void Register(NativeMobyDependencyRead read,Func<NativeByteExtent,byte[]> reader)
    {
        if(read.Extent.Space.Revision!=NativeAddressRevision.Original)
            throw new InvalidDataException("Generated storage cannot be registered as Original source.");
        if(_reads.TryGetValue(read.Extent,out var prior))
        {
            if(prior.Read.ExpectedSha256!=read.ExpectedSha256||prior.Reader!=reader)
                throw new InvalidDataException("An exact source extent cannot change its retained producer or preimage.");
        }
        else _reads.Add(read.Extent,(read,reader));
    }
    private void RequireOwners()
    {
        var current=_host.CurrentExecutableAncestor;
        _host.RequireAncestry(current,Source);
        var parent=current.FamilyCompositionAncestor??throw new InvalidDataException("Chest storage requires the actual mixed family executable.");
        _resources.RequireLockedChestResourceAncestry(parent,Source);
        if(!ReferenceEquals(_resources.BaseBodyAncestor,current.BodyAncestor)||
            !ReferenceEquals(_resources.BaseBodyAncestor.HostAncestor,_host.HostAncestor))
            throw new InvalidDataException("Chest storage lost its exact resource/current executable/Host chain.");
        if(_terrain is not null)
        {
            if(!ReferenceEquals(_terrain.ResourceAncestor,_resources)||!ReferenceEquals(_terrain.HostAncestor,_host))
                throw new InvalidDataException("Tiled storage lost the actual terrain/resource/Host tuple.");
            _terrain.RequireAncestry(_terrain.IntentAncestor,_terrain.PlacementAncestor);
        }
    }
    private void RequireRetainedBody(ReadOnlySpan<byte> bytes)
    {
        if(_terrain is null){_resources.RequireExactLevelData(bytes);return;}
        if(!bytes.SequenceEqual(_bodySnapshot))throw new InvalidDataException("Tiled storage changed its complete closed-producer Body snapshot.");
    }
    private static int Word(ReadOnlySpan<byte> bytes,int at)=>BinaryPrimitives.ReadInt32LittleEndian(bytes[at..]);
    private static string Hash(ReadOnlySpan<byte> bytes)=>Convert.ToHexStringLower(SHA256.HashData(bytes));
}
